for _n in range(0, 8):
    for _pad in (' ', '', '   '):
        for _blank_side in (0, 1):
            _rows = []
            for _i in range(_n):
                _q = _pad + f'问题{_n - _i}' + _pad
                _a = f'答案{_i}' + _pad
                if _i % 2 == _blank_side:
                    _a = _pad
                _rows.append({'question': _q, 'answer': _a, 'source': 'tag'})
            _before = [{k: v for k, v in r.items()} for r in _rows]
            _out = clean(_rows)
            _want = [{'question': f'问题{_n - _i}', 'answer': f'答案{_i}'}
                     for _i in range(_n) if _i % 2 != _blank_side]
            assert _out == _want, (_n, _pad, _blank_side, _out, _want)
            for _r in _out:
                assert set(_r) == {'question', 'answer'}, ('多余键', _r)
            assert _rows == _before, 'clean 不应该改动传入的字典'
